BQ.icon = function (name, cls = '', title = '') {
  const d = BQ.ICONS[name] || BQ.ICONS.question;
  const aria = title ? `role="img" aria-label="${title}"` : 'aria-hidden="true"';
  return `<svg class="${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round" ${aria}><path d="${d}"/></svg>`;
};

